#include "EntityStoreRuntime.hpp"
namespace elysium::save {bool EntityStoreRuntime::put(EntityRecord e,std::string&w){if(!e.id){w="invalid entity";return false;}for(auto&c:e.components){if(!c.type||!c.schemaVersion){w="invalid component record";return false;}if(c.trait==PersistenceTrait::No&&!c.payload.empty()){w="NO component must not persist payload";return false;}if(c.trait==PersistenceTrait::Derived&&!c.payload.empty()){w="DERIVED component must rebuild";return false;}}auto i=rows_.find(e.id);if(i!=rows_.end()&&e.revision<i->second.revision){w="stale entity revision";return false;}rows_[e.id]=std::move(e);return true;}std::optional<EntityRecord>EntityStoreRuntime::get(StableId id)const{auto i=rows_.find(id);if(i==rows_.end())return std::nullopt;return i->second;}bool EntityStoreRuntime::resolveReference(StableId from,StableId to,std::string&w)const{if(!rows_.count(from)){w="source unresolved";return false;}if(!rows_.count(to)){w="target unresolved/tombstone";return false;}return true;}}
